from collections import Counter, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out


def _is_corner_shape(cells):
    # The component is contained in the union of one full row and one full column,
    # with both arms represented. This captures L-shaped objects at any scale.
    if len(cells) < 3:
        return False
    rows = {r for r, _ in cells}
    cols = {c for _, c in cells}
    for r in rows:
        for c in cols:
            if len(rows) > 1 and len(cols) > 1 and all(y == r or x == c for y, x in cells):
                return True
    return False


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, background)
    # A compact L is the color cue; propagate its color to the largest other
    # component with the same corner/L structure.
    keys = [(color, cells) for color, cells in comps
            if len(cells) == 3 and _is_corner_shape(cells)]
    for key_color, key_cells in keys:
        targets = [(color, cells) for color, cells in comps
                   if color != key_color and _is_corner_shape(cells)]
        if targets:
            target_color, target_cells = max(targets, key=lambda item: len(item[1]))
            result = [row[:] for row in grid]
            for r, c in target_cells:
                result[r][c] = key_color
            return result
    return [row[:] for row in grid]
