from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return bg, result


def _l_info(cells):
    """Return corner and signed arms for a perfect one-cell-thick L."""
    if len(cells) < 3:
        return None
    rows = {r for r, _ in cells}
    cols = {c for _, c in cells}
    for cr in rows:
        for cc in cols:
            if not all(r == cr or c == cc for r, c in cells):
                continue
            # L must be connected through the corner, and both arms must exist.
            vertical = sorted(r for r, c in cells if c == cc)
            horizontal = sorted(c for r, c in cells if r == cr)
            if len(vertical) + len(horizontal) - 1 != len(cells):
                continue
            if cr not in vertical or cc not in horizontal:
                continue
            vr = -1 if min(vertical) < cr else 1
            hc = -1 if min(horizontal) < cc else 1
            vlen, hlen = len(vertical), len(horizontal)
            return (cr, cc, vr, hc, vlen, hlen)
    return None


def transform(grid):
    bg, comps = _components(grid)
    ls = [(color, cells, _l_info(cells)) for color, cells in comps]
    ls = [x for x in ls if x[2] is not None]
    if not ls:
        return [row[:] for row in grid]

    # The smallest L-shaped object is the direction/color key; larger Ls are
    # ordinary scene objects. Its arms indicate the opposite open quadrant.
    key_color, key_cells, info = min(ls, key=lambda x: len(x[1]))
    cr, cc, vr, hc, vlen, hlen = info
    candidates = []
    for color, cells in comps:
        if color == key_color:
            continue
        cy = sum(r for r, _ in cells) / len(cells)
        cx = sum(c for _, c in cells) / len(cells)
        # Opposite side of each key arm. If arms differ in length, use the
        # opposite half-plane of the longer arm; if tied, use the opposite quadrant.
        if vlen > hlen:
            ok = (cy - cr) * vr < 0
        elif hlen > vlen:
            ok = (cx - cc) * hc < 0
        else:
            ok = (cy - cr) * vr < 0 and (cx - cc) * hc < 0
        if ok:
            candidates.append((color, cells))
    if not candidates:
        return [row[:] for row in grid]

    # In a directional half-plane, the target is the component nearest the
    # diagonal line extending from the key's corner into the indicated region.
    # Use centroid distance for deterministic ranking.
    def rank(item):
        _, cells = item
        cy = sum(r for r, _ in cells) / len(cells)
        cx = sum(c for _, c in cells) / len(cells)
        return (cy - cr) ** 2 + (cx - cc) ** 2

    _, target = min(candidates, key=rank)
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out


