def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result


def _l_info(cells):
    if len(cells) < 3:
        return None
    for cr in {r for r, _ in cells}:
        for cc in {c for _, c in cells}:
            if not all(r == cr or c == cc for r, c in cells):
                continue
            vertical = sorted(r for r, c in cells if c == cc)
            horizontal = sorted(c for r, c in cells if r == cr)
            if len(vertical) + len(horizontal) - 1 != len(cells):
                continue
            vr = -1 if min(vertical) < cr else 1
            hc = -1 if min(horizontal) < cc else 1
