def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    if not colors:
        return [row[:] for row in grid]
    # The lone marked color forms an interrupted rectangular/linear drawing.
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, _ in pts); r1 = max(r for r, _ in pts)
    c0 = min(c for _, c in pts); c1 = max(c for _, c in pts)
    out = [row[:] for row in grid]
    # Complete missing cells along all straight runs of aligned marks.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == color]
        if len(cs) >= 2:
            for c in range(min(cs), max(cs) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == color]
        if len(rs) >= 2:
            for r in range(min(rs), max(rs) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    # Close the outer rectangular frame implied by the extreme marks.
    for c in range(c0, c1 + 1):
        if out[r0][c] == bg: out[r0][c] = 2
        if out[r1][c] == bg: out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if out[r][c0] == bg: out[r][c0] = 2
