def transform(grid):
    """Project marker rays between equal-length opposite border rails.

    A marker's coordinate selects an offset in one rail. Extend its ray toward
    that rail, turn the marker into endpoint color 4, and project the same
    offset inward from the opposite rail across the full interior.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    if h < 2 or w < 2:
        return out
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    # Find a unique equal-length, non-background run on opposite borders.
    candidates = []
    for axis in ('horizontal', 'vertical'):
        edge_len = w if axis == 'horizontal' else h
        n_lines = h if axis == 'horizontal' else w
        for color in set(v for row in grid for v in row if v != bg):
            runs = []
            for edge in (0, n_lines - 1):
                vals = grid[edge] if axis == 'horizontal' else [grid[r][edge] for r in range(h)]
                i = 0
                while i < edge_len:
                    if vals[i] != color:
                        i += 1
                        continue
                    j = i + 1
                    while j < edge_len and vals[j] == color:
                        j += 1
                    runs.append((edge, i, j))
                    i = j
            for a in runs:
                for b in runs:
                    if a[0] == 0 and b[0] == n_lines - 1 and (a[2] - a[1]) == (b[2] - b[1]):
                        candidates.append((axis, color, a[1], b[1], a[2] - a[1]))
    if not candidates:
        return out
    # The relevant pair is the one whose edge-coordinate spans contain markers.
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in {x[1] for x in candidates}]
    viable = []
    for cand in candidates:
        axis, rail, start_a, start_b, length = cand
        coord = 1 if axis == 'horizontal' else 0
        count = sum(start_a <= (c if coord else r) < start_a + length or
                    start_b <= (c if coord else r) < start_b + length
                    for r, c, _ in markers)
        if count:
            viable.append((count, cand))
    if not viable:
        return out
    _, (axis, rail, start_a, start_b, length) = max(viable, key=lambda x: x[0])
    is_horizontal = axis == 'horizontal'
    edge_len = w if is_horizontal else h
    n_lines = h if is_horizontal else w
    # Identify a single marker color, excluding background and rails.
    marker_colors = [grid[r][c] for r, c, _ in markers
                     if grid[r][c] != rail]
    if not marker_colors:
        return out
    marker_color = max(set(marker_colors), key=marker_colors.count)
    for r, c, value in markers:
        if value != marker_color:
            continue
        pos = c if is_horizontal else r
        if start_a <= pos < start_a + length:
            side, start, other = 0, start_a, start_b
        elif start_b <= pos < start_b + length:
            side, start, other = n_lines - 1, start_b, start_a
        else:
            continue
        offset = pos - start
        # Source ray extends from the marker toward its associated border.
        if is_horizontal:
            step = -1 if side == 0 else 1
            rr = r + step
            while 0 <= rr < h and rr != side:
                if grid[rr][c] == bg:
                    out[rr][c] = marker_color
                rr += step
            out[r][c] = 4
            counterpart = other + offset
            for rr in range(1, h - 1):
                if grid[rr][counterpart] == bg:
                    out[rr][counterpart] = marker_color
        else:
            step = -1 if side == 0 else 1
            cc = c + step
            while 0 <= cc < w and cc != side:
                if grid[r][cc] == bg:
                    out[r][cc] = marker_color
                cc += step
            out[r][c] = 4
            counterpart = other + offset
            for cc in range(1, w - 1):
                if grid[counterpart][cc] == bg:
                    out[counterpart][cc] = marker_color
    return out

