from collections import defaultdict


def transform(grid):
    """Extend the 3-phase diagonal color pattern across the whole grid."""
    h, w = len(grid), len(grid[0])
    phase_colors = defaultdict(set)
    color_phases = defaultdict(set)
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                phase = (c - r) % 3
                phase_colors[phase].add(color)
                color_phases[color].add(phase)

    # A one-phase color is the distinct diagonal; the other color fills
    # the remaining two phases. This also handles clipped stripe segments.
    singleton = [color for color, phases in color_phases.items() if len(phases) == 1]
    if singleton:
        marked = singleton[0]
        marked_phase = next(iter(color_phases[marked]))
        other = next((color for color in color_phases if color != marked), marked)
        return [[marked if (c - r) % 3 == marked_phase else other
                 for c in range(w)] for r in range(h)]

    # Fallback: use the most consistently observed color for each phase.
    phase_color = {}
    for phase in range(3):
        counts = defaultdict(int)
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color and (c - r) % 3 == phase:
                    counts[color] += 1
        if counts:
            phase_color[phase] = max(counts, key=counts.get)
    default = next(iter(phase_color.values()), 0)
    return [[phase_color.get((c - r) % 3, default) for c in range(w)]
            for r in range(h)]


